        synchronized(PlanningAccount.class){if(!openedCalendarBinding.equals(PlanningAccount.bindingHash(this)))throw CalendarAuthorization.failure("CALENDAR_SETTINGS_CHANGED");android.database.sqlite.SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{JSONObject config=AppointmentRuntime.settings(store);config.put("calendar_enabled",false);AppointmentRuntime.saveSettings(this,store,config,openedSettingsHash[0]);if(!PlanningAccount.prefs(this).edit().remove("calendar_id").commit())throw new java.io.IOException("Trennung nicht gesichert.");db.setTransactionSuccessful();}finally{db.endTransaction();}openedCalendarBinding=PlanningAccount.bindingHash(this);}
